@pytest.mark.parametrize("backend", ["memory", "sqlite"]) @pytest.mark.parametrize("explicit_first", [True, False]) def test_identical_capture_and_explicit_fact_retain_explicit_authority( tmp_path, backend, explicit_first ): store = InMemoryStore() if backend == "memory" else SQLiteStore(str(tmp_path / "merge.sqlite")) scope = {"scope": "project", "scope_id": "a", "user_profile_id": "p"} explicit = MemoryChunk( content="Use SQLite", embedding=[1.0, 0.0], version=2 if explicit_first else 1, metadata={ **scope, "source": "explicit_correction" if explicit_first else "explicit_remember", "assertion_status": "asserted", "source_event_ids": ["explicit-event"], "source_roles": ["user"], "encoding_diagnostics": {}, "host": "claude-code", "session_id": "correction-session", }, ) captured = MemoryChunk( content="Use SQLite", embedding=[1.0, 0.0], metadata={ **scope, "source": "captured_passthrough", "assertion_status": "unknown", "source_event_ids": ["captured-event"], "source_roles": ["user"], "encoding_diagnostics": {"surprisal_status": "disabled"}, "host": "codex", "session_id": "captured-session", }, ) first, second = (explicit, captured) if explicit_first else (captured, explicit) try: stored = store.upsert_canonical(first) merged = store.upsert_canonical(second) assert merged.id == stored.id assert len(store.get_all()) == 1 assert assertion_status(merged) == "asserted" assert merged.metadata["source"] == ( "explicit_correction" if explicit_first else "explicit_remember" ) assert merged.version == (2 if explicit_first else 1) > assert set(merged.metadata["source_event_ids"]) == {"explicit-event", "captured-event"} E AssertionError: assert {'captured-event'} == {'captured-ev...plicit-event'} E E Extra items in the right set: E 'explicit-event' E Use -v to get more diff
